def choose_move(observation):
    def clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def first_pos(items):
        if not items:
            return None
        for item in items:
            if isinstance(item, (list, tuple)) and len(item) >= 2:
                return item[0], item[1]
        return None

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    env = observation.get("environment_name", "resource_collection")
    self_pos = observation.get("self_position") or (0, 0)
    opp_pos = observation.get("opponent_position") or (0, 0)
    sx, sy = self_pos[0], self_pos[1]
    ox, oy = opp_pos[0], opp_pos[1]
    width = observation.get("grid_width", 0) or 0
    height = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [clamp_step(sx, ox), clamp_step(sy, oy)]
        corners = [(0, 0), (0, max(0, height - 1)), (max(0, width - 1), 0), (max(0, width - 1), max(0, height - 1))]
        target = corners[0]
        best_score = -1
        for c in corners:
            score = manhattan(c, (ox, oy))
            if score > best_score:
                best_score = score
                target = c
        return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        best = first_pos(targets)
        if best is None:
            if width and height:
                best = (width // 2, height // 2)
            else:
                return [0, 0]
        return [clamp_step(sx, best[0]), clamp_step(sy, best[1])]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    resource = first_pos(resources)

    if resource is None:
        if ox == sx and oy == sy:
            return [0, 0]
        return [clamp_step(sx, ox), clamp_step(sy, oy)]

    dist_to_opp = manhattan((sx, sy), (ox, oy))
    dist_to_res = manhattan((sx, sy), resource)

    if dist_to_opp <= 1 and dist_to_res <= 2:
        dx = clamp_step(ox, sx)
        dy = clamp_step(oy, sy)
        if dx != 0 or dy != 0:
            return [dx, dy]

    if dist_to_opp < dist_to_res and dist_to_opp <= 2:
        return [clamp_step(ox, sx), clamp_step(oy, sy)]

    return [clamp_step(sx, resource[0]), clamp_step(sy, resource[1])]

